// ── Reading Cache-Control and ETag in browser ─────────────────
async function fetchWithCacheInfo(url) {
  const res = await fetch(url);
  console.log('Cache-Control:', res.headers.get('cache-control'));
  console.log('ETag:', res.headers.get('etag'));
  console.log('Age:', res.headers.get('age')); // seconds since cached by CDN
  return res.json();
}

// ── Forcing cache bypass ──────────────────────────────────────
async function fetchFresh(url) {
  return fetch(url, { cache: 'no-store' });
  // Other fetch cache modes:
  // 'default'      — browser default cache behavior
  // 'no-cache'     — always revalidate (conditional GET)
  // 'force-cache'  — use cache even if stale
  // 'reload'       — bypass cache, but update it with response
  // 'no-store'     — never cache the response
}

// ── Cookie management (document.cookie is low-level) ─────────
function setCookie(name, value, options = {}) {
  const {
    maxAge   = 3600,
    path     = '/',
    secure   = true,
    sameSite = 'Strict',
  } = options;
  // HttpOnly cannot be set from JS (that's the point)
  document.cookie = [
    `${encodeURIComponent(name)}=${encodeURIComponent(value)}`,
    `Max-Age=${maxAge}`,
    `Path=${path}`,
    secure   ? 'Secure'              : '',
    `SameSite=${sameSite}`,
  ].filter(Boolean).join('; ');
}

function getCookie(name) {
  const match = document.cookie
    .split('; ')
    .find(row => row.startsWith(encodeURIComponent(name) + '='));
  return match ? decodeURIComponent(match.split('=')[1]) : null;
}

function deleteCookie(name) {
  // Set Max-Age=0 to expire immediately
  document.cookie = `${encodeURIComponent(name)}=; Max-Age=0; Path=/`;
}

// ── CORS credential requests ──────────────────────────────────
// By default, fetch() does NOT send cookies cross-origin
// To include cookies: set credentials: 'include'
// Server must respond with Access-Control-Allow-Credentials: true
// AND Access-Control-Allow-Origin must be a specific origin (not *)
const res = fetch('https://api.example.com/profile', {
  credentials: 'include',
});

